import React, { useEffect, useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import "./MovieDetails.css";

function MovieDetails() {
  const { id } = useParams();
  const history = useHistory();
  const [movie, setMovie] = useState(null);

  useEffect(() => {
    fetch(`/api/movies/${id}`)
      .then(res => res.json())
      .then(data => setMovie(data));
  }, [id]);

  const formatDate = dateStr => {
    if (!dateStr) return "Unknown";
    
    // Original format is DD/MM/YY
    const parts = dateStr.split("/");
    if (parts.length !== 3) return dateStr;
    
    let [day, month, year] = parts;
    year = parseInt(year) < 50 ? "20" + year : "19" + year;
    
    // Create Date object (month is 0-indexed in Date constructor, so subtract 1)
    const date = new Date(year, parseInt(month) - 1, day);
    
    // Localize the date using the browser's native API
    return date.toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  if (!movie) {
    return (
      <div className="details-container" style={{ textAlign: "center", padding: "100px 20px" }}>
        <h2 style={{ color: "var(--accent-color)" }}>Loading...</h2>
      </div>
    );
  }

  return (
    <div className="details-container">
      <button className="back-button" onClick={() => history.push("/")}>
        <span style={{ marginRight: "8px" }}>←</span> Back to Movies
      </button>

      <h1 className="movie-title">{movie.title}</h1>

      {movie.tagline && <p className="movie-tagline">"{movie.tagline}"</p>}

      <div className="movie-overview">{movie.overview}</div>

      <div className="meta-grid">
        <div className="meta-item">
          <span className="meta-label">Status</span>
          <span className="meta-value">
            <span className="status-badge">{movie.status}</span>
          </span>
        </div>

        <div className="meta-item">
          <span className="meta-label">Release Date</span>
          <span className="meta-value">{formatDate(movie.release_date)}</span>
        </div>

        <div className="meta-item">
          <span className="meta-label">Runtime</span>
          <span className="meta-value">{movie.runtime} minutes</span>
        </div>

        <div className="meta-item">
          <span className="meta-label">Rating</span>
          <span className="meta-value rating">
            <span style={{ marginRight: "6px" }}>⭐</span>
            {movie.vote_average.toFixed(1)} / 10
          </span>
        </div>
      </div>
    </div>
  );
}

export default MovieDetails;
